#include <zephyr/posix/time.h>
#include <zephyr/kernel.h>
#include <errno.h>
#include <zephyr/sys/util.h>

/*
 * The POSIX clock functions (clock_getres, clock_gettime, clock_settime, nanosleep)
 * are implemented here.
 */

int clock_getres(clockid_t clock_id, struct timespec *res)
{
    if (res == NULL) {
        errno = EFAULT;
        return -1;
    }

    switch (clock_id) {
    case CLOCK_MONOTONIC:
    case CLOCK_REALTIME:
        res->tv_sec = 0;
        /*
         * The resolution of CLOCK_MONOTONIC and CLOCK_REALTIME
         * is tied to the system clock tick.
         * CONFIG_SYS_CLOCK_TICKS_PER_SEC defines the number of ticks per second.
         * The resolution in nanoseconds is NSEC_PER_SEC / CONFIG_SYS_CLOCK_TICKS_PER_SEC.
         * Ensure CONFIG_SYS_CLOCK_TICKS_PER_SEC is positive to avoid division by zero.
         */
        if (CONFIG_SYS_CLOCK_TICKS_PER_SEC > 0) {
            res->tv_nsec = NSEC_PER_SEC / CONFIG_SYS_CLOCK_TICKS_PER_SEC;
        } else {
            /* Fallback for unusual configurations, e.g., 1ms resolution */
            res->tv_nsec = 1000000; /* 1 millisecond */
        }
        break;
#ifdef CONFIG_POSIX_CLOCK_MONOTONIC_RAW
    case CLOCK_MONOTONIC_RAW:
        /*
         * For raw monotonic clock, resolution might be higher,
         * but for simplicity, we can use the same system tick resolution
         * or a more precise hardware timer resolution if available.
         * For now, assume system tick resolution.
         */
        res->tv_sec = 0;
        if (CONFIG_SYS_CLOCK_TICKS_PER_SEC > 0) {
            res->tv_nsec = NSEC_PER_SEC / CONFIG_SYS_CLOCK_TICKS_PER_SEC;
        } else {
            res->tv_nsec = 1000000;
        }
        break;
#endif /* CONFIG_POSIX_CLOCK_MONOTONIC_RAW */
    case CLOCK_BOOTTIME:
    case CLOCK_PROCESS_CPUTIME_ID:
    case CLOCK_THREAD_CPUTIME_ID:
        /* These clocks are not typically fully supported or have specific
         * hardware dependencies. Return ENOSYS for now.
         */
        errno = ENOSYS;
        return -1;
    default:
        errno = EINVAL;
        return -1;
    }

    return 0;
}

int clock_gettime(clockid_t clock_id, struct timespec *ts)
{
    if (ts == NULL) {
        errno = EFAULT;
        return -1;
    }

    switch (clock_id) {
    case CLOCK_MONOTONIC:
    case CLOCK_REALTIME: {
        /* k_uptime_get() returns milliseconds (s64_t) */
        s64_t ms = k_uptime_get();

        ts->tv_sec = ms / 1000;
        ts->tv_nsec = (ms % 1000) * 1000000;
        break;
    }
#ifdef CONFIG_POSIX_CLOCK_MONOTONIC_RAW
    case CLOCK_MONOTONIC_RAW:
        /* For raw monotonic clock, use a hardware counter if available,
         * otherwise fallback to system uptime.
         * For now, let's use system uptime.
         */
        {
            s64_t ms = k_uptime_get();
            ts->tv_sec = ms / 1000;
            ts->tv_nsec = (ms % 1000) * 1000000;
        }
        break;
#endif /* CONFIG_POSIX_CLOCK_MONOTONIC_RAW */
    case CLOCK_BOOTTIME:
    case CLOCK_PROCESS_CPUTIME_ID:
    case CLOCK_THREAD_CPUTIME_ID:
        errno = ENOSYS;
        return -1;
    default:
        errno = EINVAL;
        return -1;
    }

    return 0;
}

int clock_settime(clockid_t clock_id, const struct timespec *ts)
{
    /* Zephyr does not typically allow setting CLOCK_MONOTONIC or CLOCK_REALTIME
     * directly from user space in a simple way.
     * CLOCK_REALTIME might be settable if there's an RTC driver.
     * For now, return ENOSYS for most cases.
     */

    if (ts == NULL) {
        errno = EFAULT;
        return -1;
    }

    switch (clock_id) {
    case CLOCK_REALTIME:
        /* If an RTC driver is available and supports setting time, implement it here.
         * For now, assume not supported.
         */
        errno = ENOSYS;
        return -1;
    case CLOCK_MONOTONIC:
    case CLOCK_MONOTONIC_RAW:
    case CLOCK_BOOTTIME:
    case CLOCK_PROCESS_CPUTIME_ID:
    case CLOCK_THREAD_CPUTIME_ID:
        errno = ENOSYS; /* These clocks are not settable */
        return -1;
    default:
        errno = EINVAL;
        return -1;
    }
}

int nanosleep(const struct timespec *rqtp, struct timespec *rmtp)
{
    if (rqtp == NULL) {
        errno = EFAULT;
        return -1;
    }

    if (rqtp->tv_sec < 0 || rqtp->tv_nsec < 0 || rqtp->tv_nsec >= NSEC_PER_SEC) {
        errno = EINVAL;
        return -1;
    }

    /* Convert timespec to milliseconds for k_sleep. */
    s64_t total_ms = (s64_t)rqtp->tv_sec * 1000 + rqtp->tv_nsec / 1000000;

    /* Handle potential overflow if rqtp->tv_sec is very large,
     * or if the total_ms calculation results in a negative value due to overflow.
     * k_sleep takes k_timeout_t, which is s32_t for K_MSEC.
     * If total_ms exceeds S32_MAX, it will be capped by K_MSEC.
     */
    if (total_ms < 0) {
        total_ms = K_FOREVER; /* Sleep indefinitely or max possible */
    }

    k_sleep(K_MSEC(total_ms));

    if (rmtp != NULL) {
        /* Zephyr's k_sleep is blocking and does not typically return remaining time.
         * For simplicity, assume full sleep completed.
         */
        rmtp->tv_sec = 0;
        rmtp->tv_nsec = 0;
    }

    return 0;
}
